package github

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os/exec"
	"strconv"
	"strings"
	"sync"
)

var (
	ghOnce      sync.Once
	ghInstalled bool
)

// IsAvailable returns true if `gh` CLI is on PATH.
func IsAvailable() bool {
	ghOnce.Do(func() {
		_, err := exec.LookPath("gh")
		ghInstalled = err == nil
	})
	return ghInstalled
}

// ResetAvailability resets the cached gh availability check.
// Intended for testing only.
func ResetAvailability() {
	ghOnce = sync.Once{}
	ghInstalled = false
}

// runGH executes a gh command and returns stdout.
func runGH(args ...string) (string, error) {
	cmd := exec.Command("gh", args...)
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	if err := cmd.Run(); err != nil {
		return "", fmt.Errorf("gh %s: %s", strings.Join(args, " "), strings.TrimSpace(stderr.String()))
	}
	return strings.TrimSpace(stdout.String()), nil
}

// PR represents a GitHub pull request.
type PR struct {
	Number         int              `json:"number"`
	HeadRefName    string           `json:"headRefName"`
	State          string           `json:"state"`
	ReviewRequests []ReviewRequest  `json:"reviewRequests"`
	LatestReviews  []Review         `json:"latestReviews"`
	StatusChecks   []StatusCheckRun `json:"statusCheckRollup"`
}

// ReviewRequest represents a pending review request.
type ReviewRequest struct {
	Login string `json:"login"`
}

// Review represents a completed review.
type Review struct {
	Author struct {
		Login string `json:"login"`
	} `json:"author"`
	State string `json:"state"` // APPROVED, CHANGES_REQUESTED, COMMENTED
}

// StatusCheckRun represents a CI check.
type StatusCheckRun struct {
	Name       string `json:"name"`
	State      string `json:"state"`      // SUCCESS, FAILURE, PENDING, etc.
	Conclusion string `json:"conclusion"` // SUCCESS, FAILURE, SKIPPED, TIMED_OUT, CANCELLED, ""
}

// Result classifies a CI check as "pass", "fail", or "pending".
func (c StatusCheckRun) Result() string {
	switch {
	case c.Conclusion == "SUCCESS" || c.Conclusion == "SKIPPED" || c.State == "SUCCESS":
		return "pass"
	case c.Conclusion == "FAILURE" || c.Conclusion == "TIMED_OUT" || c.Conclusion == "CANCELLED" || c.State == "FAILURE" || c.State == "ERROR":
		return "fail"
	default:
		return "pending"
	}
}

// ReviewSummary aggregates review counts.
type ReviewSummary struct {
	Approved int
	Changes  int
	Pending  int
}

// CISummary aggregates CI check counts.
type CISummary struct {
	Pass    int
	Fail    int
	Pending int
	Total   int
}

// GetReviewSummary computes review state counts.
func (pr *PR) GetReviewSummary() ReviewSummary {
	return getReviewSummary(pr.ReviewRequests, pr.LatestReviews)
}

// GetCISummary computes CI check state counts.
func (pr *PR) GetCISummary() CISummary {
	return getCISummary(pr.StatusChecks)
}

// getReviewSummary computes review state counts from requests and reviews.
// A pending re-review request supersedes a stale completed review.
func getReviewSummary(requests []ReviewRequest, reviews []Review) ReviewSummary {
	reRequested := make(map[string]bool)
	for _, rr := range requests {
		if rr.Login != "" {
			reRequested[rr.Login] = true
		}
	}

	var s ReviewSummary
	seen := make(map[string]bool)
	for _, r := range reviews {
		login := r.Author.Login
		if login == "" || r.State == "COMMENTED" {
			continue
		}
		seen[login] = true
		if reRequested[login] {
			s.Pending++
			continue
		}
		switch r.State {
		case "APPROVED":
			s.Approved++
		case "CHANGES_REQUESTED":
			s.Changes++
		}
	}
	for _, rr := range requests {
		if rr.Login != "" && !seen[rr.Login] {
			seen[rr.Login] = true
			s.Pending++
		}
	}
	return s
}

// getCISummary computes CI check state counts from status checks.
// Checks with empty names (GitHub summary checks) are excluded.
func getCISummary(checks []StatusCheckRun) CISummary {
	var s CISummary
	for _, c := range checks {
		if c.Name == "" {
			continue
		}
		s.Total++
		switch c.Result() {
		case "pass":
			s.Pass++
		case "fail":
			s.Fail++
		default:
			s.Pending++
		}
	}
	return s
}

// ListPRs fetches PRs in a given state with full review/CI data.
func ListPRs(state string) ([]PR, error) {
	if !IsAvailable() {
		return nil, nil
	}

	fields := "number,headRefName"
	if state == "open" {
		fields = "number,headRefName,reviewRequests,latestReviews,statusCheckRollup"
	}

	out, err := runGH("pr", "list", "--state", state, "--json", fields, "--limit", "50")
	if err != nil {
		return nil, err
	}

	var prs []PR
	if err := json.Unmarshal([]byte(out), &prs); err != nil {
		return nil, err
	}
	return prs, nil
}

// PRDetail is the rich PR info used by the dashboard detail panel.
// Fetched on demand — kept separate from the lighter `PR` returned by ListPRs.
type PRDetail struct {
	Number int    `json:"number"`
	Title  string `json:"title"`
	Body   string `json:"body"`
	Author struct {
		Login string `json:"login"`
	} `json:"author"`
	StatusChecks []StatusCheckRun `json:"statusCheckRollup"`
}

// GetPRDetail fetches title/body/author and named CI checks for one PR in a
// single gh call. Returns (nil, nil) when gh isn't installed.
func GetPRDetail(number int) (*PRDetail, error) {
	if !IsAvailable() {
		return nil, nil
	}
	out, err := runGH("pr", "view", strconv.Itoa(number),
		"--json", "number,title,body,author,statusCheckRollup")
	if err != nil {
		return nil, err
	}
	var d PRDetail
	if err := json.Unmarshal([]byte(out), &d); err != nil {
		return nil, err
	}
	return &d, nil
}

// FindPRForBranch returns the first PR matching the branch name and state.
func FindPRForBranch(prs []PR, branch string) *PR {
	for i := range prs {
		if prs[i].HeadRefName == branch {
			return &prs[i]
		}
	}
	return nil
}

// GetPRForBranch fetches the PR for a specific branch.
// Returns (nil, nil) if gh is not available or no PR exists.
func GetPRForBranch(branch string) (*PR, error) {
	if !IsAvailable() {
		return nil, nil
	}
	out, err := runGH("pr", "list", "--head", branch, "--json", "number,state", "--limit", "1")
	if err != nil {
		return nil, err
	}
	var prs []PR
	if err := json.Unmarshal([]byte(out), &prs); err != nil {
		return nil, err
	}
	if len(prs) == 0 {
		return nil, nil
	}
	return &prs[0], nil
}

// PRInfo holds lightweight PR metadata for checkout.
type PRInfo struct {
	Number      int    `json:"number"`
	Title       string `json:"title"`
	HeadRefName string `json:"headRefName"`
	State       string `json:"state"`
}

// GetPRByNumber fetches PR metadata by number.
func GetPRByNumber(number int) (*PRInfo, error) {
	if !IsAvailable() {
		return nil, fmt.Errorf("gh not installed")
	}
	out, err := runGH("pr", "view", fmt.Sprintf("%d", number), "--json", "number,title,headRefName,state")
	if err != nil {
		return nil, err
	}
	var info PRInfo
	if err := json.Unmarshal([]byte(out), &info); err != nil {
		return nil, err
	}
	return &info, nil
}

// RepoSlug returns the "owner/repo" string.
func RepoSlug() (string, error) {
	if !IsAvailable() {
		return "", fmt.Errorf("gh not installed")
	}
	return runGH("repo", "view", "--json", "nameWithOwner", "-q", ".nameWithOwner")
}

// PRLabel represents a label on a PR.
type PRLabel struct {
	Name string `json:"name"`
}

// PRDetails holds full PR metadata for recreation after branch rename.
type PRDetails struct {
	Number      int       `json:"number"`
	Title       string    `json:"title"`
	Body        string    `json:"body"`
	BaseRefName string    `json:"baseRefName"`
	IsDraft     bool      `json:"isDraft"`
	Labels      []PRLabel `json:"labels"`
}

// GetPRDetails fetches full details for the open PR on a branch.
func GetPRDetails(branch string) (*PRDetails, error) {
	if !IsAvailable() {
		return nil, nil
	}
	out, err := runGH("pr", "list", "--head", branch, "--state", "open",
		"--json", "number,title,body,baseRefName,isDraft,labels", "--limit", "1")
	if err != nil {
		return nil, err
	}
	var prs []PRDetails
	if err := json.Unmarshal([]byte(out), &prs); err != nil {
		return nil, err
	}
	if len(prs) == 0 {
		return nil, nil
	}
	return &prs[0], nil
}

// WatchStatus holds detailed PR state from `gh pr view`, including fields
// not available from `gh pr list` (mergeStateStatus, mergeable).
type WatchStatus struct {
	Number           int              `json:"number"`
	Title            string           `json:"title"`
	State            string           `json:"state"` // OPEN, CLOSED, MERGED
	HeadRefName      string           `json:"headRefName"`
	MergeStateStatus string           `json:"mergeStateStatus"` // CLEAN, BLOCKED, BEHIND, DRAFT, DIRTY, UNKNOWN
	Mergeable        string           `json:"mergeable"`        // MERGEABLE, CONFLICTING, UNKNOWN
	ReviewDecision   string           `json:"reviewDecision"`   // APPROVED, CHANGES_REQUESTED, REVIEW_REQUIRED, ""
	ReviewRequests   []ReviewRequest  `json:"reviewRequests"`
	LatestReviews    []Review         `json:"latestReviews"`
	StatusChecks     []StatusCheckRun `json:"statusCheckRollup"`
}

// GetReviewSummary computes review state counts for a WatchStatus.
func (ws *WatchStatus) GetReviewSummary() ReviewSummary {
	return getReviewSummary(ws.ReviewRequests, ws.LatestReviews)
}

// GetCISummary computes CI check state counts for a WatchStatus.
func (ws *WatchStatus) GetCISummary() CISummary {
	return getCISummary(ws.StatusChecks)
}

// FailedCheckNames returns the names of checks that failed.
func (ws *WatchStatus) FailedCheckNames() []string {
	var names []string
	for _, c := range ws.StatusChecks {
		if c.Result() == "fail" {
			names = append(names, c.Name)
		}
	}
	return names
}

// ChecksByStatus returns checks sorted into pass, fail, and pending buckets.
// Checks with empty names (GitHub summary checks) are excluded.
func (ws *WatchStatus) ChecksByStatus() (pass, fail, pending []StatusCheckRun) {
	for _, c := range ws.StatusChecks {
		if c.Name == "" {
			continue
		}
		switch c.Result() {
		case "pass":
			pass = append(pass, c)
		case "fail":
			fail = append(fail, c)
		default:
			pending = append(pending, c)
		}
	}
	return
}

// ReviewItem represents a unified review entry (completed or pending).
type ReviewItem struct {
	Login string
	State string // "approved", "changes_requested", "pending"
}

// ReviewItems merges LatestReviews and ReviewRequests into a unified list.
// A pending re-review request supersedes any previous completed review
// (the old approval is stale after new commits are pushed).
func (ws *WatchStatus) ReviewItems() []ReviewItem {
	// Build set of logins with pending re-review requests
	reRequested := make(map[string]bool)
	for _, rr := range ws.ReviewRequests {
		if rr.Login != "" {
			reRequested[rr.Login] = true
		}
	}

	seen := make(map[string]bool)
	var items []ReviewItem

	for _, r := range ws.LatestReviews {
		if r.State == "COMMENTED" {
			continue
		}
		login := r.Author.Login
		if login == "" {
			continue
		}
		seen[login] = true

		// Re-review request supersedes the stale completed review
		if reRequested[login] {
			items = append(items, ReviewItem{Login: login, State: "pending"})
			continue
		}

		state := "approved"
		if r.State == "CHANGES_REQUESTED" {
			state = "changes_requested"
		}
		items = append(items, ReviewItem{Login: login, State: state})
	}

	// Add reviewers who were requested but haven't reviewed yet
	for _, rr := range ws.ReviewRequests {
		if rr.Login != "" && !seen[rr.Login] {
			seen[rr.Login] = true
			items = append(items, ReviewItem{Login: rr.Login, State: "pending"})
		}
	}
	return items
}

// GetWatchStatus fetches detailed PR status for a branch using `gh pr view`.
func GetWatchStatus(branch string) (*WatchStatus, error) {
	if !IsAvailable() {
		return nil, fmt.Errorf("gh not installed")
	}

	fields := "number,title,state,headRefName,mergeStateStatus,mergeable,reviewDecision,reviewRequests,latestReviews,statusCheckRollup"
	out, err := runGH("pr", "view", branch, "--json", fields)
	if err != nil {
		return nil, err
	}

	var ws WatchStatus
	if err := json.Unmarshal([]byte(out), &ws); err != nil {
		return nil, err
	}
	return &ws, nil
}

// repoSettings holds the merge method settings for a repository.
type repoSettings struct {
	AllowSquashMerge bool `json:"allow_squash_merge"`
	AllowMergeCommit bool `json:"allow_merge_commit"`
	AllowRebaseMerge bool `json:"allow_rebase_merge"`
}

// GetDefaultMergeMethod returns the preferred merge method for the repo.
// Picks the first enabled method in order: squash → merge → rebase.
func GetDefaultMergeMethod() (string, error) {
	slug, err := RepoSlug()
	if err != nil {
		return "", err
	}
	out, err := runGH("api", "repos/"+slug)
	if err != nil {
		return "", err
	}
	var s repoSettings
	if err := json.Unmarshal([]byte(out), &s); err != nil {
		return "", err
	}
	switch {
	case s.AllowSquashMerge:
		return "squash", nil
	case s.AllowMergeCommit:
		return "merge", nil
	case s.AllowRebaseMerge:
		return "rebase", nil
	default:
		return "merge", nil
	}
}

// MergePR merges a pull request using the given method (squash, merge, rebase).
func MergePR(prNumber int, method string) error {
	_, err := runGH("pr", "merge", strconv.Itoa(prNumber), "--"+method)
	return err
}

// CreatePR creates a new pull request and returns the PR URL.
func CreatePR(head, base, title, body string, draft bool, labels []string) (string, error) {
	if !IsAvailable() {
		return "", fmt.Errorf("gh not installed")
	}
	args := []string{"pr", "create", "--head", head, "--base", base, "--title", title, "--body", body}
	if draft {
		args = append(args, "--draft")
	}
	for _, l := range labels {
		args = append(args, "--label", l)
	}
	return runGH(args...)
}
package cmd

import (
	"fmt"
	"strconv"

	"github.com/mvwi/wt/internal/github"
	"github.com/spf13/cobra"
)

var prCmd = &cobra.Command{
	Use:     "pr <number>",
	GroupID: groupWorkflow,
	Short:   "Checkout a PR into a worktree",
	Long: `Fetch a GitHub pull request into its own worktree.

Looks up the PR by number, resolves the branch, and creates a worktree
for it — useful for code review workflows.

Requires the GitHub CLI (gh) to be installed.`,
	Example: `  wt pr 123          Checkout PR #123 into a worktree
  wt pr 123 --init   Checkout + auto-initialize`,
	Args: cobra.ExactArgs(1),
	RunE: runPR,
}

var prDoInit bool

func init() {
	prCmd.Flags().BoolVarP(&prDoInit, "init", "i", false, "run 'wt init' after creating")
	rootCmd.AddCommand(prCmd)
}

func runPR(cmd *cobra.Command, args []string) error {
	if !github.IsAvailable() {
		return fmt.Errorf("gh CLI is required for this command (brew install gh)")
	}

	number, err := strconv.Atoi(args[0])
	if err != nil {
		return fmt.Errorf("invalid PR number: %s", args[0])
	}

	ctx, err := newContext()
	if err != nil {
		return err
	}

	pr, err := github.GetPRByNumber(number)
	if err != nil {
		return fmt.Errorf("failed to fetch PR #%d: %w", number, err)
	}

	if pr.State != "OPEN" {
		return fmt.Errorf("PR #%d is %s", number, pr.State)
	}

	name := nameFromBranch(pr.HeadRefName, ctx.Config.Remote)

	fmt.Printf("PR #%d: %s\n", pr.Number, pr.Title)
	fmt.Println()

	return createWorktreeFromRemote(ctx, name, pr.HeadRefName, prDoInit)
}
package cmd

import (
	"fmt"

	"github.com/mvwi/wt/internal/git"
	"github.com/mvwi/wt/internal/ui"
	"github.com/spf13/cobra"
)

var pullCmd = &cobra.Command{
	Use:     "pull <branch> [name]",
	GroupID: groupWorkflow,
	Short:   "Pull a remote branch into a new worktree",
	Long: `Fetch a remote branch and create a worktree for it.

This is a shorthand for "wt new [name] --from <branch>". If no name is
given, one is derived from the last segment of the branch name.`,
	Example: `  wt pull feature/login       Create worktree from remote branch
  wt pull user/sidebar card   Create worktree named "card" from remote branch
  wt pull feature/login -i    Pull + auto-initialize`,
	Args: cobra.RangeArgs(1, 2),
	RunE: runPull,
}

var pullDoInit bool

func init() {
	pullCmd.Flags().BoolVarP(&pullDoInit, "init", "i", false, "run 'wt init' after creating")
	rootCmd.AddCommand(pullCmd)
}

func runPull(cmd *cobra.Command, args []string) error {
	ctx, err := newContext()
	if err != nil {
		return err
	}

	branch := args[0]
	var name string
	if len(args) > 1 {
		name = args[1]
	}

	// Fetch to get latest refs
	spin := ui.NewSpinner("Fetching latest refs")
	if err := git.FetchAll(ctx.Config.Remote); err != nil {
		spin.Stop()
		ui.Warn("Fetch failed: %v", err)
	} else {
		spin.Stop()
	}

	ref, isRemote, err := git.ResolveBranch(branch, ctx.Config.Remote)
	if err != nil {
		return err
	}

	if name == "" {
		name = nameFromBranch(ref, ctx.Config.Remote)
	}

	if isRemote {
		return createWorktreeFromRemote(ctx, name, ref, pullDoInit)
	}

	// Local branch — same path as wt new --from with a local branch
	wtPath := ctx.worktreePath(name)

	if isDir(wtPath) {
		return fmt.Errorf("worktree already exists: %s\n   Use wt switch %s to switch to it", wtPath, name)
	}

	fmt.Println("Creating worktree from existing branch…")
	fmt.Printf("  Directory: %s\n", wtPath)
	fmt.Printf("  Branch: %s\n", ref)
	fmt.Println()

	if err := git.AddWorktreeFromExisting(wtPath, ref); err != nil {
		return fmt.Errorf("failed to create worktree: %w", err)
	}

	fmt.Println()
	ui.Success("Created worktree")
	fmt.Println()

	if pullDoInit {
		return runInitIn(wtPath, ctx)
	}
	printSwitchHint(name)
	return nil
}
package cmd

import (
	"fmt"
	"strconv"
	"strings"

	"github.com/mvwi/wt/internal/git"
	"github.com/mvwi/wt/internal/github"
	"github.com/mvwi/wt/internal/ui"
	"github.com/spf13/cobra"
)

var newCmd = &cobra.Command{
	Use:     "new <name>",
	Aliases: []string{"create"},
	GroupID: groupWorkflow,
	Short:   "Create a new worktree with a feature branch",
	Long: `Create a new worktree with a feature branch based on your configured base branch.

By default, creates a branch named "<prefix>/<name>" from the base branch
(configurable in .wt.toml, defaults to "main").

Use --from to create a worktree from an existing branch or PR number.`,
	Example: `  wt new sidebar-card               Create <user>/sidebar-card from base branch
  wt new --from feature/old         Create worktree from existing branch
  wt new fix --from origin/hotfix   Create worktree with custom name from remote
  wt new --from #123                Create worktree from PR #123's branch
  wt new feature --init             Create + auto-initialize`,
	Args: cobra.MaximumNArgs(1),
	RunE: runNew,
}

var (
	newFromBranch string
	newDoInit     bool
)

func init() {
	newCmd.Flags().StringVarP(&newFromBranch, "from", "f", "", "base on an existing branch or PR number")
	newCmd.Flags().BoolVarP(&newDoInit, "init", "i", false, "run 'wt init' after creating")
	rootCmd.AddCommand(newCmd)
}

func runNew(cmd *cobra.Command, args []string) error {
	ctx, err := newContext()
	if err != nil {
		return err
	}

	var name string
	if len(args) > 0 {
		name = args[0]
	}

	// --from mode: create worktree from existing branch
	if newFromBranch != "" {
		return newFromExisting(ctx, name, newFromBranch)
	}

	if name == "" {
		return fmt.Errorf("name is required\n\nUsage: wt new <name>\n       wt new --from <branch>")
	}

	return newFromBase(ctx, name)
}

func newFromExisting(ctx *cmdContext, name, fromBranch string) error {
	// Check if --from is a PR number (e.g., "#123" or "123")
	if prNumber, ok := parsePRNumber(fromBranch); ok {
		return newFromPR(ctx, name, prNumber)
	}

	// Fetch to get latest refs (needed for ResolveBranch to find remote branches)
	spin := ui.NewSpinner("Fetching latest refs")
	if err := git.FetchAll(ctx.Config.Remote); err != nil {
		spin.Stop()
		ui.Warn("Fetch failed: %v", err)
	} else {
		spin.Stop()
	}

	ref, isRemote, err := git.ResolveBranch(fromBranch, ctx.Config.Remote)
	if err != nil {
		return err
	}

	// Derive name from branch if not provided
	if name == "" {
		name = nameFromBranch(ref, ctx.Config.Remote)
	}

	if isRemote {
		return createWorktreeFromRemote(ctx, name, ref, newDoInit)
	}

	// Local branch path
	wtPath := ctx.worktreePath(name)

	if isDir(wtPath) {
		return fmt.Errorf("worktree already exists: %s\n   Use wt switch %s to switch to it", wtPath, name)
	}

	fmt.Println("Creating worktree from existing branch…")
	fmt.Printf("  Directory: %s\n", wtPath)
	fmt.Printf("  Branch: %s\n", ref)
	fmt.Println()

	if err := git.AddWorktreeFromExisting(wtPath, ref); err != nil {
		return fmt.Errorf("failed to create worktree: %w", err)
	}

	fmt.Println()
	ui.Success("Created worktree")
	fmt.Println()

	if newDoInit {
		return runInitIn(wtPath, ctx)
	}
	printSwitchHint(name)
	return nil
}

// parsePRNumber checks if s looks like a PR number ("#123" or "123")
// and returns the parsed number if so.
func parsePRNumber(s string) (int, bool) {
	s = strings.TrimPrefix(s, "#")
	n, err := strconv.Atoi(s)
	if err != nil || n <= 0 {
		return 0, false
	}
	return n, true
}

func newFromPR(ctx *cmdContext, name string, number int) error {
	if !github.IsAvailable() {
		return fmt.Errorf("gh CLI is required to resolve PR numbers (brew install gh)")
	}

	spin := ui.NewSpinner(fmt.Sprintf("Fetching PR #%d", number))
	pr, err := github.GetPRByNumber(number)
	spin.Stop()
	if err != nil {
		return fmt.Errorf("failed to fetch PR #%d: %w", number, err)
	}

	fmt.Printf("PR #%d: %s\n", pr.Number, pr.Title)
	fmt.Println()

	if name == "" {
		name = nameFromBranch(pr.HeadRefName, ctx.Config.Remote)
	}

	return createWorktreeFromRemote(ctx, name, pr.HeadRefName, newDoInit)
}

// nameFromBranch derives a short worktree name from a branch ref.
// Takes the last segment after "/" and strips the remote prefix if present.
//
//	"origin/user/fix-login" → "fix-login"
//	"user/fix-login"        → "fix-login"
//	"fix-login"             → "fix-login"
func nameFromBranch(ref, remote string) string {
	parts := strings.Split(ref, "/")
	name := parts[len(parts)-1]
	return strings.TrimPrefix(name, remote+"/")
}

// createWorktreeFromRemote handles the common flow for checking out a remote
// branch into a new worktree: check if it already exists, fetch, create, and
// optionally run init. Used by both `wt new --from` and `wt pr`.
func createWorktreeFromRemote(ctx *cmdContext, name, remoteBranch string, doInit bool) error {
	wtPath := ctx.worktreePath(name)

	if isDir(wtPath) {
		return fmt.Errorf("worktree already exists: %s\n   Use wt switch %s to switch to it", wtPath, name)
	}

	// Fetch to get latest refs
	spin := ui.NewSpinner("Fetching latest refs")
	if err := git.FetchAll(ctx.Config.Remote); err != nil {
		spin.Stop()
		ui.Warn("Fetch failed: %v", err)
	} else {
		spin.Stop()
	}

	localBranch := strings.TrimPrefix(remoteBranch, ctx.Config.Remote+"/")
	remoteRef := ctx.Config.Remote + "/" + localBranch

	fmt.Println("Creating worktree from existing branch…")
	fmt.Printf("  Directory: %s\n", wtPath)
	fmt.Printf("  Branch: %s\n", localBranch)
	fmt.Println()

	err := git.AddWorktreeFromRemote(wtPath, localBranch, remoteRef)
	if err != nil {
		// Branch might already exist locally
		err = git.AddWorktreeFromExisting(wtPath, localBranch)
	}
	if err != nil {
		return fmt.Errorf("failed to create worktree: %w", err)
	}

	fmt.Println()
	ui.Success("Created worktree")
	fmt.Println()

	if doInit {
		return runInitIn(wtPath, ctx)
	}
	printSwitchHint(name)
	return nil
}

// printSwitchHint prints the next-step command and offers to copy it to the clipboard.
func printSwitchHint(name string) {
	switchCmd := fmt.Sprintf("wt switch %s && wt init", name)
	fmt.Printf("  → %s\n", switchCmd)
	ui.PrintCTA("wt switch "+name, "wt init")

	if ui.IsTTY() && ui.ClipboardAvailable() {
		if ui.Confirm("Copy to clipboard?", true) {
			if err := ui.CopyToClipboard(switchCmd); err != nil {
				ui.Warn("Failed to copy: %v", err)
			} else {
				ui.Success("Copied to clipboard")
			}
		}
	}
}

func newFromBase(ctx *cmdContext, name string) error {
	branch := ctx.branchName(name)
	wtPath := ctx.worktreePath(name)

	if isDir(wtPath) {
		return fmt.Errorf("worktree already exists: %s\n   Use wt switch %s to switch to it", wtPath, name)
	}

	if git.BranchExists(branch) {
		return fmt.Errorf("branch already exists: %s\n   Use wt new --from %s to create a worktree for it\n   Or wt switch %s if the worktree already exists", branch, branch, name)
	}

	fmt.Println("Creating worktree…")
	fmt.Printf("  Directory: %s\n", wtPath)
	fmt.Printf("  Branch: %s (from %s)\n", branch, ctx.Config.BaseBranch)
	fmt.Println()

	// Fetch latest base branch
	spin := ui.NewSpinner(fmt.Sprintf("Fetching %s", ctx.Config.BaseBranch))
	if err := git.Fetch(ctx.Config.Remote, ctx.Config.BaseBranch); err != nil {
		spin.Stop()
		ui.Warn("Fetch failed: %v", err)
	} else {
		spin.Stop()
	}

	if err := git.AddWorktree(wtPath, branch, ctx.baseRef()); err != nil {
		return fmt.Errorf("failed to create worktree: %w", err)
	}

	fmt.Println()
	ui.Success("Created worktree")
	fmt.Println()

	if newDoInit {
		return runInitIn(wtPath, ctx)
	}
	printSwitchHint(name)
	return nil
}

