// watchResult describes why the watch loop ended.
type watchResult struct {
	success bool
	message string
}

func runWatch(cmd *cobra.Command, args []string) error {
	if !github.IsAvailable() {
		return fmt.Errorf("gh CLI is required for this command (brew install gh)")
	}

	ctx, err := newContext()
	if err != nil {
		return err
	}

	// Resolve what to watch: PR number, worktree name, or current branch
	var ref string
	if len(args) > 0 {
		if isAllDigits(args[0]) {
			// PR number — use directly
			ref = args[0]
		} else {
			// Fuzzy-match against worktrees
			worktrees, err := git.ListWorktrees()
			if err != nil {
				return err
			}
			target, _, resolveErr := resolveWorktree(ctx, worktrees, args[0])
			if resolveErr != nil {
				return resolveErr
			}
			if target == "" {
				return fmt.Errorf("worktree not found: %s\n   Run wt list to see available worktrees", args[0])
			}
			branch, err := git.CurrentBranchIn(target)
			if err != nil {
				return fmt.Errorf("could not determine branch for worktree: %s", args[0])
			}
			ref = branch
		}
	} else {
		branch, err := git.CurrentBranch()
		if err != nil {
			return fmt.Errorf("not in a git repository or detached HEAD\n   Run this from inside a worktree")
		}

		if ctx.isBaseBranch(branch) {
			return fmt.Errorf("can't watch the base branch (%s) %s it has no associated PR\n   Switch to a feature worktree first", branch, ui.Dash)
		}
		ref = branch
	}

	// Initial fetch to verify PR exists
	ws, err := github.GetWatchStatus(ref)
	if err != nil {
		return fmt.Errorf("could not fetch PR status for %s: %w", ref, err)
	}

	// Resolve merge method once up front (2 gh calls — no need to repeat per poll)
	mergeMethod := ""
	if watchMergeFlag {
		m, err := github.GetDefaultMergeMethod()
		if err != nil {
			ui.Warn("Could not determine merge method, defaulting to merge: %v", err)
			m = "merge"
		}
		mergeMethod = m
	}

	// Print header (once)
	printWatchHeader(ws)

	// Check if already resolved
	if res := checkResolved(ws); res != nil {
		renderWatchTable(ws)
		printWatchVerdict(ws)
		if err := mergeIfRequested(ws, mergeMethod); err != nil {
			return err
		}
		printWatchCTA(ws)
		if res.success {
			return nil
		}
		return errSilent
	}

	// Set up Ctrl+C handler
	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, os.Interrupt)
	defer signal.Stop(sigCh)

	// Poll loop
	ticker := time.NewTicker(15 * time.Second)
	defer ticker.Stop()

	tableLines := renderWatchTable(ws)
	spin := ui.NewSpinnerRich(buildSpinnerMessage(ws))

	for {
		select {
		case <-sigCh:
			spin.Stop()
			fmt.Println()
			return nil

		case <-ticker.C:
			ws, err = github.GetWatchStatus(ref)
			if err != nil {
				spin.Stop()
				return fmt.Errorf("failed to fetch PR status: %w", err)
			}

			// Clear and redraw
			spin.Stop()
			ui.ClearLines(tableLines)

			if res := checkResolved(ws); res != nil {
				renderWatchTable(ws)
				printWatchVerdict(ws)
				if err := mergeIfRequested(ws, mergeMethod); err != nil {
					return err
				}
				printWatchCTA(ws)
				sendNotification(ws)
				if res.success {
