old=s[s.index('// ListPRs fetches PRs'):s.index('// PRDetail is the rich')]
new='''// ListPRs fetches PRs in a given state with full review/CI data.
// When heads are given, it fetches only PRs whose head branch matches one of
// them, which is far faster on busy repos than listing the latest 50.
func ListPRs(state string, heads ...string) ([]PR, error) {
	if !IsAvailable() {
		return nil, nil
	}

	fields := "number,headRefName"
	if state == "open" {
		fields = "number,headRefName,reviewRequests,latestReviews,statusCheckRollup"
	}
	args := []string{"pr", "list", "--state", state, "--json", fields}

	if len(heads) == 0 {
		return listPRs(append(args, "--limit", "50")...)
	}
	var all []PR
	for _, q := range headQueries(heads) {
		// shortcut: head: is a prefix match on GitHub, so a short branch name can
		// pull in extra PRs and crowd out the 100 limit; callers match exactly.
		prs, err := listPRs(append(args, "--limit", "100", "--search", q)...)
		if err != nil {
			return nil, err
		}
		all = append(all, prs...)
	}
	return all, nil
}

func listPRs(args ...string) ([]PR, error) {
	out, err := runGH(args...)
	if err != nil {
		return nil, err
	}
	var prs []PR
	if err := json.Unmarshal([]byte(out), &prs); err != nil {
		return nil, err
	}
	return prs, nil
}

// maxHeadQuery keeps each search well under GitHub's 256-character query limit,
// leaving room for the repo and state qualifiers gh adds.
const maxHeadQuery = 180

// headQueries packs "head:<branch>" terms (ORed by GitHub) into search
// strings no longer than maxHeadQuery.
func headQueries(heads []string) []string {
	var queries []string
	var cur string
	for _, h := range heads {
		term := "head:" + h
		if cur != "" && len(cur)+1+len(term) > maxHeadQuery {
			queries = append(queries, cur)
			cur = ""
		}
		if cur != "" {
			cur += " "
		}
		cur += term
	}
	if cur != "" {
		queries = append(queries, cur)
	}
	return queries
}

'''
